import { projects, type Project } from '../lib/content';
import { Icon, Action, SourceRefs } from './ui';
export function ProjectDirectory(){return <section className="container page-section"><div className="page-heading"><p className="section-number">THE ECOSYSTEM</p><h1>Find your starting point.</h1><p>Four projects. Distinct responsibilities. A direct path to their source.</p></div><div className="filter-toolbar"><div className="filter-search"><Icon name="search"/><input type="search" id="project-search" placeholder="Find a project…" aria-label="Find a project" maxLength={200}/></div><div className="filter-options" role="group" aria-label="Project category">{['All','Runtime','Storage','Companion','Framework'].map(c=><button key={c} type="button" data-category={c} aria-pressed={c==='All'}>{c}</button>)}</div></div><p id="project-count" className="result-count" aria-live="polite">4 projects</p><div className="directory-list">{projects.map((p,i)=><article key={p.id} data-project={p.id} className={`directory-project project-${p.id}`}><div className="directory-label"><span className="project-index">0{i+1}</span><span className="project-dot"></span><span>{p.category}</span></div><div><h2><a href={`/projects/${p.id}/`}>{p.name}<Icon name="external"/></a></h2><p>{p.description}</p><span className="language-label">{p.language}</span></div><div className="directory-links"><a className="text-link" href={`/projects/${p.id}/`}>Project overview<Icon name="arrow"/></a><a href={p.repo} target="_blank" rel="noopener noreferrer">Upstream source<Icon name="external"/></a></div></article>)}</div><div id="project-empty" className="empty-state" hidden><Icon name="search"/><h2>No projects match that search.</h2><p>Try another term or return to the full directory.</p><button className="button secondary" data-reset-projects="" type="button">Reset filters<Icon name="arrow"/></button></div></section>}
export function ProjectDetail({project:p}:{project:Project}){return <section className={`container page-section project-${p.id}`}><a className="back-link" href="/projects/">All projects<Icon name="arrow"/></a><div className="project-detail-hero"><div><p className="section-number"><span className="project-dot"></span>{p.category} / {p.language}</p><h1>{p.name}<span className="detail-period">.</span></h1><p className="detail-role">{p.role}</p></div><div><p className="detail-overview">{p.overview}</p><div className="hero-actions"><Action href={`/docs/${p.guide}/`}>Read the guide</Action><a className="text-link" href={p.repo} target="_blank" rel="noopener noreferrer">View source<Icon name="external"/></a></div></div></div><div className="detail-body"><div><h2>What the source describes</h2><ul className="scope-list">{p.documented.map(t=><li key={t}><Icon name="check"/>{t}</li>)}</ul><div className="callout"><Icon name="book"/><div><h3>Keep the scope visible.</h3><p>{p.limits}</p></div></div><h2>A useful next step</h2><p>Read the linked guide, inspect the upstream source, and verify the behavior that matters to your environment. This preview does not execute the project or certify its readiness.</p><a className="text-link" href="/docs/evidence/">How to read a capability claim<Icon name="arrow"/></a></div><SourceRefs ids={p.sources}/></div></section>}
